    "starter": "#include <assert.h>\n#include <limits.h>\n#include <math.h>\n#include <stdbool.h>\n#include <stddef.h>\n#include <stdint.h>\n#include <stdlib.h>\n#include <string.h>\nbool solid(const char *const *g, int h, int w, int row,\n           int col) { /* TODO: implement this function. */\n    abort();\n}\nunsigned bitmask(const char *const *g, int h, int w, int row,\n                 int col) { /* TODO: implement this function. */\n    abort();\n}",
    "solution": "#include <assert.h>\n#include <limits.h>\n#include <math.h>\n#include <stdbool.h>\n#include <stddef.h>\n#include <stdint.h>\n#include <stdlib.h>\n#include <string.h>\nbool solid(const char *const *g, int h, int w, int row, int col) {\n    return row < 0 || col < 0 || row >= h || col >= w || g[row][col] == '#';\n}\nunsigned bitmask(const char *const *g, int h, int w, int row, int col) {\n    return (solid(g, h, w, row - 1, col) ? 1u : 0u) |\n           (solid(g, h, w, row, col + 1) ? 2u : 0u) |\n           (solid(g, h, w, row + 1, col) ? 4u : 0u) |\n           (solid(g, h, w, row, col - 1) ? 8u : 0u);\n}",
