  "save_codec": {
    "starter": "#include <assert.h>\n#include <limits.h>\n#include <math.h>\n#include <stdbool.h>\n#include <stddef.h>\n#include <stdint.h>\n#include <stdlib.h>\n#include <string.h>\ntypedef struct {\n    uint32_t coins;\n    uint16_t level;\n} Save;\nuint8_t checksum(const uint8_t *p, size_t n) { /* TODO: implement this function. */\n    abort();\n}\nvoid encode(Save s, uint8_t *out) { /* TODO: implement this function. */ abort(); }\nbool decode(const uint8_t *b, size_t n,\n            Save *out) { /* TODO: implement this function. */\n    abort();\n}",
    "solution": "#include <assert.h>\n#include <limits.h>\n#include <math.h>\n#include <stdbool.h>\n#include <stddef.h>\n#include <stdint.h>\n#include <stdlib.h>\n#include <string.h>\ntypedef struct {\n    uint32_t coins;\n    uint16_t level;\n} Save;\nuint8_t checksum(const uint8_t *p, size_t n) {\n    uint8_t sum = 0;\n    for (size_t i = 0; i < n; i++)\n        sum = (uint8_t)(sum + p[i]);\n    return sum;\n}\nvoid encode(Save s, uint8_t *out) {\n    out[0] = 'S';\n    out[1] = 2;\n    for (int i = 0; i < 4; i++)\n        out[2 + i] = (uint8_t)(s.coins >> (8 * i));\n    out[6] = (uint8_t)s.level;\n    out[7] = (uint8_t)(s.level >> 8);\n    out[8] = checksum(out, 8);\n}\nbool decode(const uint8_t *b, size_t n, Save *out) {\n    if (n < 2 || b[0] != 'S')\n        return false;\n    if (b[1] == 2) {\n        if (n != 9 || b[8] != checksum(b, 8))\n            return false;\n        out->coins = (uint32_t)b[2] | ((uint32_t)b[3] << 8) | ((uint32_t)b[4] << 16) |\n                     ((uint32_t)b[5] << 24);\n        out->level = (uint16_t)(b[6] | (b[7] << 8));\n        return true;\n    }\n    if (b[1] == 1) {\n        if (n != 6 || b[5] != checksum(b, 5))\n            return false;\n        out->coins = b[2] | (b[3] << 8);\n        out->level = b[4];\n        return true;\n    }\n    return false;\n}",
    "tests": "int main(void) {\n    uint8_t b[9];\n    encode((Save){0x01020304, 0x0506}, b);\n    uint8_t expected[] = {0x53, 2, 4, 3, 2, 1, 6, 5, 0x6A};\n    assert(memcmp(b, expected, 9) == 0);\n    Save out;\n    assert(decode(b, 9, &out) && out.coins == 0x01020304 && out.level == 0x0506);\n    b[8] ^= 1;\n    assert(!decode(b, 9, &out));\n    uint8_t v1[] = {0x53, 1, 0x2C, 1, 7, 0x88};\n    assert(decode(v1, 6, &out) && out.coins == 300 && out.level == 7);\n    assert(!decode(NULL, 0, &out));\n    return 0;\n}\n"
  },
